// src/index.js
import './App.scss';
import './Button.scss';
import './Responsive1500.scss';
import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import { worker } from "./mocks/browser";

// MSW 먼저 준비시키고, 준비된 뒤에 React 렌더
(async function bootstrap() {
  const tries = [
    { url: `${firstBase()}mockServiceWorker.js`, scope: firstBase() },
    { url: `${pathBase()}mockServiceWorker.js`,  scope: pathBase()  },
    { url: `/mockServiceWorker.js`,              scope: `/`         },
  ];
  for (const sw of tries) {
    try {
      await Promise.race([
        worker.start({ serviceWorker: sw, onUnhandledRequest: "warn" }),
        new Promise((_, r) => setTimeout(() => r(new Error("sw-timeout")), 2000)),
      ]);
      console.log("[MSW] registered:", sw.url);
      break;
    } catch (e) {
      console.warn("[MSW] register failed:", sw.url, e?.message || e);
    }
  }
  const root = ReactDOM.createRoot(document.getElementById("root"));
  root.render(
    <React.StrictMode>
      <App />
    </React.StrictMode>
  );
})();

function firstBase() {
  const vite = (typeof import.meta !== "undefined" && import.meta.env && import.meta.env.BASE_URL) || "";
  const cra  = (typeof process !== "undefined" && process.env && process.env.PUBLIC_URL) || "";
  const picked = cra || vite || "/";
  return picked.endsWith("/") ? picked : picked + "/";
}
function pathBase() {
  const p = (typeof window !== "undefined" && window.location && window.location.pathname) || "/";
  const seg = p.split("/").filter(Boolean)[0];
  return seg ? `/${seg}/` : "/";
}
